CREATE OR REPLACE FUNCTION public.close_shift(p_shift_id uuid, p_actual_cash numeric, p_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_shift RECORD;
    v_expected NUMERIC(12,2);
BEGIN
    SELECT * INTO v_shift FROM shifts WHERE id = p_shift_id;
    IF v_shift IS NULL THEN
        RAISE EXCEPTION 'Shift not found';
    END IF;

    IF NOT user_belongs_to_business(v_shift.business_id) THEN
        RAISE EXCEPTION 'User does not belong to shift business';
    END IF;

    IF v_shift.cashier_id <> current_user_id()
       AND NOT user_has_permission(v_shift.business_id, 'manage_users') THEN
        RAISE EXCEPTION 'Only the cashier or a manager can close this shift';
    END IF;

    IF v_shift.status <> 'open' THEN
        RAISE EXCEPTION 'Shift is not open';
    END IF;

    SELECT COALESCE(SUM(p.amount), 0)
    INTO v_expected
    FROM sales s
    JOIN payments p ON p.id = s.payment_id
    WHERE s.cashier_id = v_shift.cashier_id
      AND s.branch_id = v_shift.branch_id
      AND s.created_at >= v_shift.opened_at
      AND s.created_at <= now()
      AND p.method = 'cash';

    v_expected := v_expected + v_shift.opening_float;

    UPDATE shifts
    SET closed_at = now(),
        actual_cash = p_actual_cash,
        expected_cash = v_expected,
        discrepancy = p_actual_cash - v_expected,
        status = 'closed',
        notes = p_notes,
        updated_at = now()
    WHERE id = p_shift_id;

    INSERT INTO activity_logs (business_id, branch_id, actor_id, action, entity_table, entity_id, metadata)
    VALUES (v_shift.business_id, v_shift.branch_id, v_shift.cashier_id, 'shift_closed', 'shifts', p_shift_id,
            jsonb_build_object('expected_cash', v_expected,
                               'actual_cash', p_actual_cash,
                               'discrepancy', p_actual_cash - v_expected));
END;
$function$

CREATE OR REPLACE FUNCTION public.create_checkout_intent(p_business_id uuid, p_branch_id uuid, p_cashier_id uuid, p_idempotency_key uuid, p_items jsonb, p_total_amount bigint, p_method text DEFAULT 'card'::text)
 RETURNS TABLE(intent_id uuid, cart_id uuid, reference text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_cart_id UUID;
    v_intent_id UUID;
    v_reference TEXT;
    v_item JSONB;
    v_product_id UUID;
    v_quantity INT;
    v_unit_price DECIMAL(12, 2);
    v_is_quick_sale BOOLEAN;
    v_computed_total DECIMAL(12, 2) := 0;
BEGIN
    IF v_user_id IS NULL OR v_user_id != p_cashier_id THEN
        RAISE EXCEPTION 'Caller must be the cashier';
    END IF;

    IF NOT user_belongs_to_business(p_business_id) THEN
        RAISE EXCEPTION 'Cashier does not belong to business';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM branches
        WHERE id = p_branch_id
          AND business_id = p_business_id
          AND deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'Invalid branch';
    END IF;

    -- Idempotency: return existing intent if the caller retries.
    SELECT pi.id, pi.cart_id, pi.provider_reference
    INTO v_intent_id, v_cart_id, v_reference
    FROM payment_intents pi
    WHERE pi.idempotency_key = p_idempotency_key
      AND pi.business_id = p_business_id;

    IF v_intent_id IS NOT NULL THEN
        RETURN QUERY SELECT v_intent_id, v_cart_id, v_reference;
        RETURN;
    END IF;

    IF jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'Cart is empty';
    END IF;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_quantity := (v_item->>'quantity')::INT;
        v_is_quick_sale := COALESCE((v_item->>'is_quick_sale')::BOOLEAN, false);

        IF v_quantity IS NULL OR v_quantity <= 0 THEN
            RAISE EXCEPTION 'Invalid item: %', v_item;
        END IF;

        IF v_is_quick_sale THEN
            v_unit_price := (v_item->>'unit_price')::DECIMAL(12, 2);
            IF v_unit_price IS NULL OR v_unit_price < 0 THEN
                RAISE EXCEPTION 'Quick sale item missing unit_price: %', v_item;
            END IF;
        ELSE
            v_product_id := (v_item->>'product_id')::UUID;

            IF v_product_id IS NULL THEN
                RAISE EXCEPTION 'Invalid item: %', v_item;
            END IF;

            SELECT selling_price
            INTO v_unit_price
            FROM products
            WHERE id = v_product_id
              AND business_id = p_business_id
              AND deleted_at IS NULL;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'Product % not found', v_product_id;
            END IF;

            IF NOT EXISTS (
                SELECT 1
                FROM inventory
                WHERE product_id = v_product_id
                  AND branch_id = p_branch_id
                  AND quantity >= v_quantity
            ) THEN
                RAISE EXCEPTION 'Insufficient stock for product %', v_product_id;
            END IF;
        END IF;

        v_computed_total := v_computed_total + (v_unit_price * v_quantity);
    END LOOP;

    -- Compare in pesewas; v_computed_total is GHS decimals, p_total_amount is pesewas.
    IF ROUND(v_computed_total * 100)::bigint != p_total_amount THEN
        RAISE EXCEPTION 'Total amount mismatch: computed % pesewas, received %', ROUND(v_computed_total * 100)::bigint, p_total_amount;
    END IF;

    INSERT INTO carts (business_id, branch_id, cashier_id, status)
    VALUES (p_business_id, p_branch_id, p_cashier_id, 'ACTIVE')
    RETURNING id INTO v_cart_id;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_quantity := (v_item->>'quantity')::INT;
        v_is_quick_sale := COALESCE((v_item->>'is_quick_sale')::BOOLEAN, false);

        IF v_is_quick_sale THEN
            v_unit_price := (v_item->>'unit_price')::DECIMAL(12, 2);
            v_product_id := NULL;
        ELSE
            v_product_id := (v_item->>'product_id')::UUID;
            v_unit_price := (
                SELECT selling_price
                FROM products
                WHERE id = v_product_id AND business_id = p_business_id
            );
        END IF;

        INSERT INTO cart_items (cart_id, product_id, quantity, unit_price)
        VALUES (v_cart_id, v_product_id, v_quantity, v_unit_price);
    END LOOP;

    v_reference := p_idempotency_key::text;

    INSERT INTO payment_intents (
        business_id, cart_id, amount, currency, idempotency_key,
        provider, provider_reference, status, created_by
    )
    VALUES (
        p_business_id, v_cart_id, v_computed_total, 'GHS', p_idempotency_key,
        'paystack', v_reference, 'initiated', p_cashier_id
    )
    RETURNING id INTO v_intent_id;

    RETURN QUERY SELECT v_intent_id, v_cart_id, v_reference;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_branch_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    -- Service-role / internal calls (Paystack webhook finalization) have no
    -- auth.uid(); they are trusted and exempt.
    IF auth.uid() IS NULL THEN
        RETURN NEW;
    END IF;
    IF NEW.branch_id IS NOT NULL
       AND NEW.branch_id NOT IN (SELECT user_accessible_branches(NEW.business_id)) THEN
        RAISE EXCEPTION 'User % not authorized for branch %', auth.uid(), NEW.branch_id;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_daily_sales(p_business_id uuid, p_branch_id uuid, p_since date)
 RETURNS SETOF mv_daily_sales
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    IF NOT user_belongs_to_business(p_business_id) THEN
        RAISE EXCEPTION 'Access denied';
    END IF;
    IF p_branch_id NOT IN (SELECT user_accessible_branches(p_business_id)) THEN
        RAISE EXCEPTION 'Access denied for branch';
    END IF;
    RETURN QUERY
        SELECT * FROM mv_daily_sales
        WHERE business_id = p_business_id AND branch_id = p_branch_id
          AND sale_date >= p_since;
END;
$function$

