CREATE OR REPLACE FUNCTION public.open_shift(p_business_id uuid, p_branch_id uuid, p_cashier_id uuid, p_opening_float numeric DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_existing UUID;
    v_shift_id UUID;
BEGIN
    IF NOT user_belongs_to_business(p_business_id) THEN
        RAISE EXCEPTION 'User does not belong to business';
    END IF;

    IF auth.uid() IS NULL OR auth.uid() <> p_cashier_id THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    SELECT id INTO v_existing
    FROM shifts
    WHERE cashier_id = p_cashier_id
      AND branch_id = p_branch_id
      AND status = 'open'
    LIMIT 1;

    IF v_existing IS NOT NULL THEN
        RAISE EXCEPTION 'Cashier already has an open shift';
    END IF;

    INSERT INTO shifts (business_id, branch_id, cashier_id, opening_float)
    VALUES (p_business_id, p_branch_id, p_cashier_id, p_opening_float)
    RETURNING id INTO v_shift_id;

    INSERT INTO activity_logs (business_id, branch_id, actor_id, action, entity_table, entity_id, metadata)
    VALUES (p_business_id, p_branch_id, p_cashier_id, 'shift_opened', 'shifts', v_shift_id,
            jsonb_build_object('opening_float', p_opening_float));

    RETURN v_shift_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_checkout_cash(p_business_id uuid, p_branch_id uuid, p_cashier_id uuid, p_idempotency_key uuid, p_items jsonb, p_total_amount bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_cart_id UUID;
    v_intent_id UUID;
    v_payment_id UUID;
    v_invoice_id UUID;
    v_sale_id UUID;
    v_item JSONB;
    v_product_id UUID;
    v_quantity INT;
    v_unit_price DECIMAL(12, 2);
    v_is_quick_sale BOOLEAN;
    v_quick_sale_name TEXT;
    v_computed_total DECIMAL(12, 2) := 0;
    v_existing_sale_id UUID;
    v_invoice_number VARCHAR(100);
BEGIN
    -- Caller must be the authenticated cashier and belong to the business.
    IF v_user_id IS NULL OR v_user_id != p_cashier_id THEN
        RAISE EXCEPTION 'Caller must be the cashier';
    END IF;

    IF NOT user_belongs_to_business(p_business_id) THEN
        RAISE EXCEPTION 'Cashier does not belong to business';
    END IF;

    -- Branch must be owned by the business and active.
    IF NOT EXISTS (
        SELECT 1
        FROM branches
        WHERE id = p_branch_id
          AND business_id = p_business_id
          AND deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'Invalid branch';
    END IF;

    -- Idempotency: if a sale already exists for this key, return it.
    SELECT s.id
    INTO v_existing_sale_id
    FROM payment_intents pi
    LEFT JOIN sales s ON s.payment_id = pi.legacy_payment_id
    WHERE pi.idempotency_key = p_idempotency_key
      AND pi.business_id = p_business_id
    LIMIT 1;

    IF v_existing_sale_id IS NOT NULL THEN
        RETURN v_existing_sale_id;
    END IF;

    IF jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'Cart is empty';
    END IF;

    -- Validate items, resolve prices, and compute total.
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_quantity := (v_item->>'quantity')::INT;
        v_is_quick_sale := COALESCE((v_item->>'is_quick_sale')::BOOLEAN, false);

        IF v_quantity IS NULL OR v_quantity <= 0 THEN
            RAISE EXCEPTION 'Invalid item: %', v_item;
        END IF;

        IF v_is_quick_sale THEN
            -- Quick sale: use the client-supplied price; no product/inventory lookup.
            v_unit_price := (v_item->>'unit_price')::DECIMAL(12, 2);
            IF v_unit_price IS NULL OR v_unit_price < 0 THEN
                RAISE EXCEPTION 'Quick sale item missing unit_price: %', v_item;
            END IF;
        ELSE
            -- Catalog item: resolve price from the products table.
            v_product_id := (v_item->>'product_id')::UUID;

            IF v_product_id IS NULL THEN
                RAISE EXCEPTION 'Invalid item: %', v_item;
            END IF;

            SELECT selling_price
            INTO v_unit_price
            FROM products
            WHERE id = v_product_id
              AND business_id = p_business_id
              AND deleted_at IS NULL;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'Product % not found', v_product_id;
            END IF;

            -- Prevent oversell at checkout time.
            IF NOT EXISTS (
                SELECT 1
                FROM inventory
                WHERE product_id = v_product_id
                  AND branch_id = p_branch_id
                  AND quantity >= v_quantity
            ) THEN
                RAISE EXCEPTION 'Insufficient stock for product %', v_product_id;
            END IF;
        END IF;

        v_computed_total := v_computed_total + (v_unit_price * v_quantity);
    END LOOP;

    -- Compare in pesewas; v_computed_total is GHS decimals, p_total_amount is pesewas.
    IF ROUND(v_computed_total * 100)::bigint != p_total_amount THEN
        RAISE EXCEPTION 'Total amount mismatch: computed % pesewas, received %', ROUND(v_computed_total * 100)::bigint, p_total_amount;
    END IF;

    -- Persist cart.
    INSERT INTO carts (business_id, branch_id, cashier_id, status)
    VALUES (p_business_id, p_branch_id, p_cashier_id, 'CHECKED_OUT')
    RETURNING id INTO v_cart_id;

    -- Persist cart items.
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_quantity := (v_item->>'quantity')::INT;
        v_is_quick_sale := COALESCE((v_item->>'is_quick_sale')::BOOLEAN, false);

        IF v_is_quick_sale THEN
            v_unit_price := (v_item->>'unit_price')::DECIMAL(12, 2);
            v_product_id := NULL;
        ELSE
            v_product_id := (v_item->>'product_id')::UUID;
            v_unit_price := (
                SELECT selling_price
                FROM products
                WHERE id = v_product_id AND business_id = p_business_id
            );
        END IF;

        INSERT INTO cart_items (cart_id, product_id, quantity, unit_price)
        VALUES (v_cart_id, v_product_id, v_quantity, v_unit_price);
    END LOOP;

    -- Create a completed payment intent for the cash sale.
    INSERT INTO payment_intents (
        business_id, cart_id, amount, currency, idempotency_key,
        provider, status, created_by
    )
    VALUES (
        p_business_id, v_cart_id, v_computed_total, 'GHS', p_idempotency_key,
        'cash', 'completed', p_cashier_id
    )
    RETURNING id INTO v_intent_id;

    -- Append the capture event to the immutable ledger.
    INSERT INTO payment_events (payment_intent_id, event_type, provider, occurred_at)
    VALUES (v_intent_id, 'payment_captured', 'cash', NOW());

    -- Keep the legacy payment table in sync for receipts and dashboards.
    INSERT INTO payments (business_id, cashier_id, method, amount, status, provider_reference)
    VALUES (p_business_id, p_cashier_id, 'cash', v_computed_total, 'COMPLETED', p_idempotency_key::text)
    RETURNING id INTO v_payment_id;

    UPDATE payment_intents
    SET legacy_payment_id = v_payment_id
    WHERE id = v_intent_id;

    -- Invoice and sale records.
    v_invoice_number := 'INV-' || to_char(NOW(), 'YYYYMMDD') || '-' || substr(v_intent_id::text, 1, 8);

    INSERT INTO invoices (business_id, branch_id, invoice_number, cashier_id, payment_id, subtotal, tax, total)
    VALUES (p_business_id, p_branch_id, v_invoice_number, p_cashier_id, v_payment_id, v_computed_total, 0, v_computed_total)
    RETURNING id INTO v_invoice_id;

    INSERT INTO sales (business_id, branch_id, invoice_id, payment_id, cashier_id)
    VALUES (p_business_id, p_branch_id, v_invoice_id, v_payment_id, p_cashier_id)
    RETURNING id INTO v_sale_id;

    -- Decrement stock and write audit logs (catalog items only).
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_quantity := (v_item->>'quantity')::INT;
        v_is_quick_sale := COALESCE((v_item->>'is_quick_sale')::BOOLEAN, false);
        v_quick_sale_name := v_item->>'quick_sale_name';

        IF v_is_quick_sale THEN
            v_unit_price := (v_item->>'unit_price')::DECIMAL(12, 2);
            -- Quick sale: no product_id, no inventory decrement.
            INSERT INTO sale_items (sale_id, product_id, quantity, unit_price, subtotal, is_quick_sale, quick_sale_name)
            VALUES (v_sale_id, NULL, v_quantity, v_unit_price, v_unit_price * v_quantity, true, v_quick_sale_name);
        ELSE
            v_product_id := (v_item->>'product_id')::UUID;
            v_unit_price := (
                SELECT selling_price
                FROM products
                WHERE id = v_product_id AND business_id = p_business_id
            );

            INSERT INTO sale_items (sale_id, product_id, quantity, unit_price, subtotal)
            VALUES (v_sale_id, v_product_id, v_quantity, v_unit_price, v_unit_price * v_quantity);

            UPDATE inventory
            SET quantity = quantity - v_quantity
            WHERE product_id = v_product_id AND branch_id = p_branch_id;

            INSERT INTO inventory_logs (business_id, branch_id, product_id, old_quantity, new_quantity, change_amount, reason, actor_id)
            SELECT business_id, branch_id, product_id, quantity + v_quantity, quantity, -v_quantity, 'sale', p_cashier_id
            FROM inventory
            WHERE product_id = v_product_id AND branch_id = p_branch_id;
        END IF;
    END LOOP;

    INSERT INTO activity_logs (business_id, actor_id, action, entity_table, entity_id, metadata)
    VALUES (
        p_business_id, p_cashier_id, 'sale_completed', 'sales', v_sale_id,
        jsonb_build_object('payment_intent_id', v_intent_id, 'total', v_computed_total, 'method', 'cash')
    );

    RETURN v_sale_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_payment_capture(p_payment_intent_id uuid, p_event_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_pi RECORD;
BEGIN
    -- Lock the intent to serialize concurrent webhooks.
    SELECT * INTO v_pi
    FROM payment_intents WHERE id = p_payment_intent_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Payment intent % not found', p_payment_intent_id;
    END IF;

    -- The unique index on payment_processing_markers(payment_intent_id) ensures
    -- only the first caller wins; subsequent calls return false.
    BEGIN
        INSERT INTO payment_processing_markers (payment_intent_id, event_id)
        VALUES (p_payment_intent_id, p_event_id);
    EXCEPTION WHEN unique_violation THEN
        RETURN false;
    END;

    RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_refund(p_business_id uuid, p_branch_id uuid, p_cashier_id uuid, p_sale_id uuid, p_items jsonb, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_refund_id UUID;
    v_total NUMERIC(12,2) := 0;
    item JSONB;
    v_sale_item RECORD;
    v_sale_item_id UUID;
    v_product_id UUID;
    v_quantity INTEGER;
    v_unit_price NUMERIC(12,2);
    v_subtotal NUMERIC(12,2);
    v_already_refunded INTEGER;
    v_old_quantity INTEGER;
    v_existing_refund_id UUID;
BEGIN
    -- Authorization and ownership checks
    IF NOT user_belongs_to_business(p_business_id) THEN
        RAISE EXCEPTION 'User does not belong to business';
    END IF;

    IF auth.uid() IS NULL OR auth.uid() <> p_cashier_id THEN
        RAISE EXCEPTION 'Unauthorized cashier';
    END IF;

    -- Verify sale exists and belongs to business/branch
    PERFORM 1 FROM sales
    WHERE id = p_sale_id
      AND business_id = p_business_id
      AND branch_id = p_branch_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Sale not found in branch';
    END IF;

    -- Idempotency replay: if a refund already exists for this key, return it
    -- without re-processing items or restocking inventory.
    IF p_idempotency_key IS NOT NULL THEN
        SELECT id INTO v_existing_refund_id
        FROM refunds
        WHERE business_id = p_business_id
          AND branch_id = p_branch_id
          AND sale_id = p_sale_id
          AND idempotency_key = p_idempotency_key
        LIMIT 1;

        IF v_existing_refund_id IS NOT NULL THEN
            RETURN v_existing_refund_id;
        END IF;
    END IF;

    -- Create refund record
    INSERT INTO refunds (business_id, branch_id, sale_id, cashier_id, reason, total_amount, idempotency_key)
    VALUES (p_business_id, p_branch_id, p_sale_id, p_cashier_id, p_reason, 0, p_idempotency_key)
    RETURNING id INTO v_refund_id;

    -- Process each item
    FOR item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
        v_sale_item_id := (item->>'sale_item_id')::UUID;
        v_quantity := (item->>'quantity')::INTEGER;

        SELECT si.id, si.product_id, si.quantity, si.unit_price
        INTO v_sale_item
        FROM sale_items si
        JOIN sales s ON s.id = si.sale_id
        WHERE si.id = v_sale_item_id
          AND s.id = p_sale_id
          AND s.business_id = p_business_id;

        IF v_sale_item.id IS NULL THEN
            RAISE EXCEPTION 'Invalid sale item: %', v_sale_item_id;
        END IF;

        v_already_refunded := refunded_quantity(v_sale_item_id);
        IF v_already_refunded + v_quantity > v_sale_item.quantity THEN
            RAISE EXCEPTION 'Refund quantity exceeds sold quantity for item %', v_sale_item_id;
        END IF;

        v_product_id := v_sale_item.product_id;
        v_unit_price := v_sale_item.unit_price;
        v_subtotal := v_unit_price * v_quantity;
        v_total := v_total + v_subtotal;

        INSERT INTO refund_items (refund_id, sale_item_id, product_id, quantity, unit_price, subtotal)
        VALUES (v_refund_id, v_sale_item_id, v_product_id, v_quantity, v_unit_price, v_subtotal);

        -- Return inventory to stock
        SELECT quantity INTO v_old_quantity
        FROM inventory
        WHERE product_id = v_product_id
          AND branch_id = p_branch_id;

        UPDATE inventory
        SET quantity = quantity + v_quantity,
            updated_at = now()
        WHERE product_id = v_product_id
          AND branch_id = p_branch_id;

        -- Insert inventory log
        INSERT INTO inventory_logs (business_id, branch_id, product_id, old_quantity, new_quantity, change_amount, reason, actor_id)
        VALUES (p_business_id, p_branch_id, v_product_id, v_old_quantity, v_old_quantity + v_quantity, v_quantity, 'refund', p_cashier_id);
    END LOOP;

    -- Update refund total
    UPDATE refunds
    SET total_amount = v_total,
        updated_at = now()
    WHERE id = v_refund_id;

    -- Audit log
    INSERT INTO activity_logs (business_id, branch_id, actor_id, action, entity_table, entity_id, metadata)
    VALUES (p_business_id, p_branch_id, p_cashier_id, 'refund_created', 'refunds', v_refund_id,
            jsonb_build_object('sale_id', p_sale_id, 'amount', v_total));

    RETURN v_refund_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_stock_in(p_branch_id uuid, p_product_id uuid, p_quantity integer, p_reason text DEFAULT 'delivery'::text, p_idempotency_key text DEFAULT (gen_random_uuid())::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_business_id  UUID;
    v_current_qty  INT;
BEGIN
    SELECT business_id INTO v_business_id
    FROM branches WHERE id = p_branch_id AND deleted_at IS NULL;
    IF v_business_id IS NULL THEN
        RAISE EXCEPTION 'Branch not found';
    END IF;

    -- Authorization: caller must belong to the business, hold manage_inventory,
    -- and be scoped to this branch (owners/accountants see all branches).
    IF NOT user_belongs_to_business(v_business_id) THEN
        RAISE EXCEPTION 'User does not belong to business';
    END IF;
    IF NOT user_has_permission(v_business_id, 'manage_inventory') THEN
        RAISE EXCEPTION 'Missing manage_inventory permission';
    END IF;
    IF p_branch_id NOT IN (SELECT user_accessible_branches(v_business_id)) THEN
        RAISE EXCEPTION 'User not authorized for this branch';
    END IF;

    IF p_quantity IS NULL OR p_quantity <= 0 THEN
        RAISE EXCEPTION 'Quantity must be positive';
    END IF;

    -- Idempotency: skip if this key was already processed.
    IF EXISTS (SELECT 1 FROM inventory_logs WHERE idempotency_key = p_idempotency_key) THEN
        RETURN;
    END IF;

    SELECT quantity INTO v_current_qty
    FROM inventory WHERE product_id = p_product_id AND branch_id = p_branch_id;

    IF v_current_qty IS NULL THEN
        INSERT INTO inventory (product_id, branch_id, business_id, quantity, reorder_level)
        VALUES (p_product_id, p_branch_id, v_business_id, p_quantity, 5);
        v_current_qty := 0;
    ELSE
        UPDATE inventory
        SET quantity = v_current_qty + p_quantity, updated_at = now()
        WHERE product_id = p_product_id AND branch_id = p_branch_id;
    END IF;

    INSERT INTO inventory_logs (
        id, business_id, branch_id, product_id,
        old_quantity, new_quantity, change_amount,
        reason, actor_id, idempotency_key
    ) VALUES (
        gen_random_uuid(), v_business_id, p_branch_id, p_product_id,
        v_current_qty, v_current_qty + p_quantity, p_quantity,
        p_reason, auth.uid(), p_idempotency_key
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.safe_finalize_sale(p_payment_intent_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_pi RECORD;
    v_cart RECORD;
    v_item RECORD;
    v_branch_id UUID;
    v_subtotal DECIMAL := 0;
    v_old_qty INT;
    v_new_qty INT;
    v_payment_id UUID;
    v_invoice_id UUID;
    v_sale_id UUID;
    v_invoice_number VARCHAR;
    v_seq INT;
    v_channel TEXT;
    v_method VARCHAR(50);
BEGIN
    -- Fetch and lock the intent.
    SELECT * INTO v_pi
    FROM payment_intents WHERE id = p_payment_intent_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Payment intent % not found', p_payment_intent_id;
    END IF;

    -- Idempotently attach the capture marker inside this transaction.
    BEGIN
        INSERT INTO payment_processing_markers (payment_intent_id, event_id)
        SELECT p_payment_intent_id, id
        FROM payment_events
        WHERE payment_intent_id = p_payment_intent_id
          AND event_type = 'payment_captured'
        LIMIT 1;
    EXCEPTION WHEN unique_violation THEN
        NULL;
    END;

    IF NOT EXISTS (
        SELECT 1 FROM payment_processing_markers WHERE payment_intent_id = p_payment_intent_id
    ) THEN
        RAISE EXCEPTION 'No payment_captured event found for payment intent %', p_payment_intent_id;
    END IF;

    -- Lock the cart; fail loudly if it is missing or not active.
    SELECT * INTO v_cart FROM carts WHERE id = v_pi.cart_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cart % not found for payment intent %', v_pi.cart_id, p_payment_intent_id;
    END IF;

    IF v_cart.status != 'ACTIVE' THEN
        RAISE EXCEPTION 'Cart % is not active. Already processed?', v_pi.cart_id;
    END IF;

    v_branch_id := v_cart.branch_id;

    -- Decrement branch inventory for each cart item and write immutable inventory logs.
    FOR v_item IN
        SELECT product_id, quantity, unit_price FROM cart_items
        WHERE cart_id = v_pi.cart_id ORDER BY product_id
    LOOP
        v_subtotal := v_subtotal + (v_item.quantity * v_item.unit_price);

        SELECT quantity INTO v_old_qty FROM inventory
        WHERE product_id = v_item.product_id AND branch_id = v_branch_id
        FOR UPDATE;

        IF NOT FOUND OR v_old_qty < v_item.quantity THEN
            RAISE EXCEPTION 'Insufficient stock or missing inventory for product %', v_item.product_id;
        END IF;

        UPDATE inventory
        SET quantity = quantity - v_item.quantity, updated_at = NOW()
        WHERE product_id = v_item.product_id AND branch_id = v_branch_id
        RETURNING quantity INTO v_new_qty;

        INSERT INTO inventory_logs (
            business_id, branch_id, product_id, old_quantity, new_quantity,
            change_amount, reason, actor_id
        ) VALUES (
            v_pi.business_id, v_branch_id, v_item.product_id, v_old_qty, v_new_qty,
            -v_item.quantity, 'SALE_EVENT', v_pi.created_by
        );
    END LOOP;

    -- Validate the cart amount matches the intent amount before mutating anything else.
    IF TRUNC(v_subtotal, 2) != TRUNC(v_pi.amount, 2) THEN
        RAISE EXCEPTION 'Cart amount (%) does not match payment intent amount (%)', v_subtotal, v_pi.amount;
    END IF;

    -- Create the legacy payment record. We deliberately NEVER store full PAN or CVV.
    -- Derive the legacy method from the Paystack channel captured on the
    -- payment_captured event payload (Paystack sends data.channel: card,
    -- mobile_money, ussd, bank_transfer, bank, ...). This prevents MoMo and
    -- bank-transfer payments from being misreported as CARD on dashboards.
    -- payments.method is VARCHAR(50) with no CHECK constraint (see 001), so we
    -- map to the legacy CARD/MOMO/BANK_TRANSFER values without widening anything.
    SELECT COALESCE(
        NULLIF(payload->'data'->>'channel', ''),
        NULLIF(payload->>'channel', '')
    ) INTO v_channel
    FROM payment_events
    WHERE payment_intent_id = p_payment_intent_id
      AND event_type = 'payment_captured'
    ORDER BY occurred_at DESC
    LIMIT 1;

    v_method := CASE
        WHEN v_channel = 'card'              THEN 'CARD'
        WHEN v_channel = 'mobile_money'      THEN 'MOMO'
        WHEN v_channel = 'ussd'              THEN 'MOMO'
        WHEN v_channel IN ('bank_transfer', 'bank', 'bank_account') THEN 'BANK_TRANSFER'
        ELSE 'CARD'
    END;

    INSERT INTO payments (
        business_id, cashier_id, method, amount, status, provider_reference
    ) VALUES (
        v_pi.business_id, v_pi.created_by, v_method, v_pi.amount, 'SUCCESS', v_pi.provider_reference
    ) RETURNING id INTO v_payment_id;

    -- Link the legacy payment and mark the intent completed.
    UPDATE payment_intents
    SET legacy_payment_id = v_payment_id, status = 'completed'
    WHERE id = p_payment_intent_id;

    -- Generate a collision-resistant invoice number scoped by branch.
    SELECT COALESCE(MAX(CAST(SPLIT_PART(invoice_number, '-', 4) AS INT)), 0) + 1
    INTO v_seq FROM invoices
    WHERE branch_id = v_branch_id
      AND invoice_number LIKE 'INV-' || TO_CHAR(NOW(), 'YYYYMMDD') || '%';

    v_invoice_number := 'INV-' || TO_CHAR(NOW(), 'YYYYMMDD') || '-' || LPAD(v_seq::TEXT, 6, '0');

    INSERT INTO invoices (
        business_id, branch_id, invoice_number, cashier_id, payment_id, subtotal, tax, total
    ) VALUES (
        v_pi.business_id, v_branch_id, v_invoice_number, v_pi.created_by, v_payment_id,
        v_subtotal, 0, v_subtotal
    ) RETURNING id INTO v_invoice_id;

    -- Create the sale.
    INSERT INTO sales (business_id, branch_id, invoice_id, payment_id, cashier_id)
    VALUES (v_pi.business_id, v_branch_id, v_invoice_id, v_payment_id, v_pi.created_by)
    RETURNING id INTO v_sale_id;

    -- Persist line items.
    INSERT INTO sale_items (sale_id, product_id, quantity, unit_price, subtotal)
    SELECT v_sale_id, product_id, quantity, unit_price, (quantity * unit_price)
    FROM cart_items WHERE cart_id = v_pi.cart_id;

    -- Mark the cart completed.
    UPDATE carts
    SET status = 'COMPLETED', updated_at = NOW()
    WHERE id = v_pi.cart_id;

    RETURN v_sale_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.user_accessible_branches(p_business_id uuid)
 RETURNS SETOF uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user UUID := current_user_id();
    v_has_unscoped BOOLEAN;
BEGIN
    IF v_user IS NULL OR p_business_id IS NULL THEN
        RETURN;
    END IF;

    -- If the user has ANY role row with NULL branch_id for this business,
    -- they have cross-branch access (owner / accountant). Return NULL set
    -- is not directly expressible in SETOF, so we return all branch IDs
    -- of the business instead — callers treat "all branches" as no filter.
    SELECT EXISTS (
        SELECT 1 FROM user_business_roles
        WHERE user_id = v_user
          AND business_id = p_business_id
          AND branch_id IS NULL
    ) INTO v_has_unscoped;

    IF v_has_unscoped THEN
        RETURN QUERY SELECT id FROM branches
                     WHERE business_id = p_business_id AND deleted_at IS NULL;
        RETURN;
    END IF;

    -- Otherwise return only the explicitly assigned branches.
    RETURN QUERY
        SELECT ubr.branch_id
        FROM user_business_roles ubr
        WHERE ubr.user_id = v_user
          AND ubr.business_id = p_business_id
          AND ubr.branch_id IS NOT NULL;
END;
$function$
